# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import (
    URL_localhost,
    create_recipe,
    get_header,
    get_scaled_recipe,
    update_recipe,
)


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = get_header()

    recipes_POST_response = create_recipe(
        client, headers, "Scale Halving Recipe"
    )

    recipes = skyramp.get_response_value(recipes_POST_response, "")
    assert recipes is not None

    recipes_recipes_PATCH_response = update_recipe(client, headers, recipes, 4, 2)

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "recipeServings") == 4
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "recipeYieldQuantity") == 2
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "recipeIngredient.0.quantity") == 2
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "recipeIngredient.0.note") == "cups flour"
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "recipeIngredient.1") is None
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") is not None

    scale_GET_response = get_scaled_recipe(
        client,
        headers,
        skyramp.get_response_value(recipes_recipes_PATCH_response, "slug"),
        "0.5",
    )

    assert skyramp.get_response_value(scale_GET_response, "slug") == skyramp.get_response_value(
        recipes_recipes_PATCH_response, "slug"
    )
    assert skyramp.get_response_value(scale_GET_response, "recipeServings") == skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeServings"
    ) * 0.5
    assert skyramp.get_response_value(scale_GET_response, "recipeYieldQuantity") == skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeYieldQuantity"
    ) * 0.5
    assert skyramp.get_response_value(scale_GET_response, "recipeIngredient.0.quantity") == skyramp.get_response_value(
        recipes_recipes_PATCH_response, "recipeIngredient.0.quantity"
    ) * 0.5
    assert skyramp.get_response_value(scale_GET_response, "recipeIngredient.0.note") == "cups flour"
    assert skyramp.get_response_value(scale_GET_response, "recipeIngredient.1") is None


if __name__ == "__main__":
    test_integration()
